namespace {
bool makeCurveFixture(const File& file){AudioBuffer<float> audio(2,192000);for(int c=0;c<2;++c)for(int i=0;i<audio.getNumSamples();++i)audio.setSample(c,i,.12f*std::sin(i*.025));auto stream=file.createOutputStream();WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(stream?wav.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);if(!writer)return false;stream.release();return writer->writeFromAudioSampleBuffer(audio,0,audio.getNumSamples());}
Project curveSong(const File& file){auto song=emptyProject();song.title="Audio fade curve verification";song.bpm=120;song.songMode=true;song.loop=false;Clip a;a.track=0;a.length=4;a.audioPath=file.getFullPathName();a.fadeIn=.25;a.fadeInCurve=FadeCurve::sCurve;auto b=a;b.editorId=Uuid().toString();b.beat=3;b.fadeIn=0;b.fadeInCurve=FadeCurve::linear;b.fadeOut=.5;b.fadeOutCurve=FadeCurve::equalPower;song.clips={a,b};return song;}
}
void Studio::runAudioFadeCurveChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    synchronizeAutosave();perform(stop);cancelNoteTool(false);cancelPlaylistGesture();PopupMenu::dismissAllActiveMenus();auto file=folder.getChildFile("fade-curve-source.wav");check(makeCurveFixture(file),"create retained audio for fade shape verification");auto hash=projectFileToken(file);auto source=curveSong(file);
    auto reset=[&]{perform(stop);project=source;currentFile={};selectedClip=-1;selectedTrack=0;selectedNotes.clear();selectedNote=-1;undoStack.clear();redoStack.clear();publish();setPlaylistSelection({0,1},1);dirty=false;showPane(playlistPane);};
    reset();auto before=JSON::toString(projectToJson(project));check(applyAudioCrossfades(selectedPlaylistIds,revision,false,FadeCurve::equalPower)&&project.clips[0].fadeOutCurve==FadeCurve::equalPower&&project.clips[1].fadeInCurve==FadeCurve::equalPower&&undoStack.size()==1,"crossfade shape is applied to both transition ends as one Undo");
    check(project.clips[0].fadeInCurve==FadeCurve::sCurve&&project.clips[1].fadeOutCurve==FadeCurve::equalPower&&project.clips[0].fadeIn==.25,"crossfade changes retain independent outer fade shapes and lengths");auto count=undoStack.size();check(applyAudioCrossfades(selectedPlaylistIds,revision,false,FadeCurve::equalPower)&&undoStack.size()==count,"reapplying the same crossfade shape does not add empty history");auto fitted=JSON::toString(projectToJson(project));perform(undoAction);check(JSON::toString(projectToJson(project))==before,"one Undo restores original envelopes after a shape edit");perform(redoAction);check(JSON::toString(projectToJson(project))==fitted,"Redo restores both fitted nonlinear ends");setPlaylistSelection({0,1},1);
    check(applyAudioCrossfades(selectedPlaylistIds,revision,false,FadeCurve::sCurve)&&project.clips[0].fadeOutCurve==FadeCurve::sCurve&&undoStack.size()==2,"already fitted overlaps can change shape without changing duration");perform(copySelection);editCursorBeat=8;perform(pasteSelection);check(project.clips.size()==4&&project.clips[2].fadeInCurve==FadeCurve::sCurve&&project.clips[2].fadeOutCurve==FadeCurve::sCurve&&project.clips[3].fadeInCurve==FadeCurve::sCurve,"group clipboard retains independently shaped audio ends");perform(undoAction);setPlaylistSelection({0,1},1);
    selectedClip=0;setPlaylistSelection({0},0);auto old=revision;check(applyAudioFadeCurves(0,old,FadeCurve::equalPower,FadeCurve::linear)&&project.clips[0].fadeInCurve==FadeCurve::equalPower&&project.clips[0].fadeOutCurve==FadeCurve::linear,"single-clip fade controls can set independent shapes");check(!applyAudioFadeCurves(0,old,FadeCurve::linear,FadeCurve::linear),"stale fade dialogs cannot overwrite newer envelopes");auto snapshot=JSON::toString(projectToJson(project));selectedClip=1;check(!applyAudioFadeCurves(0,revision,FadeCurve::linear,FadeCurve::linear)&&JSON::toString(projectToJson(project))==snapshot,"changed primary clip selection blocks a captured fade editor");selectedClip=0;recording=true;check(!applyAudioFadeCurves(0,revision,FadeCurve::linear,FadeCurve::linear),"an active take blocks fade shape edits");recording=false;check(!applyAudioFadeCurves(0,revision,(FadeCurve)99,FadeCurve::linear),"unsupported curve choices are rejected before history or publication");
    auto saved=folder.getChildFile("curved-audio-ui.pulse");Project read;check(saveProject(project,saved).wasOk()&&loadProject(saved,read).wasOk()&&read.clips[0].fadeInCurve==FadeCurve::equalPower&&read.clips[0].fadeOutCurve==FadeCurve::linear,"native save and checked reload preserve independent shape values");setPlaylistSelection({0,1},1);perform(audioFadesClear);check(project.clips[0].fadeIn==0&&project.clips[0].fadeInCurve==FadeCurve::linear&&project.clips[1].fadeOutCurve==FadeCurve::linear,"Clear selected fades resets durations and curves together");perform(undoAction);check(project.clips[0].fadeInCurve==FadeCurve::equalPower,"Undo clear restores envelope shape metadata");
    reset();applyAudioCrossfades(selectedPlaylistIds,revision,false,FadeCurve::sCurve);setPlaylistSelection({0},0);editCursorBeat=2;splitSelectedClip();check(project.clips.size()==3&&project.clips[0].fadeInCurve==FadeCurve::sCurve&&project.clips[0].fadeOutCurve==FadeCurve::linear&&project.clips[2].fadeInCurve==FadeCurve::linear&&project.clips[2].fadeOutCurve==FadeCurve::sCurve,"split preserves outer shapes and resets the new internal boundaries");perform(undoAction);check(project.clips.size()==2&&project.clips[0].fadeOutCurve==FadeCurve::sCurve,"split Undo restores complete original shaped audio clip");
    reset();applyAudioCrossfades(selectedPlaylistIds,revision,false,FadeCurve::equalPower);playlistStart=0;playlistSpan=8;check(this->snapshot(folder.getChildFile("curved-audio-playlist.png")),"Playlist draws the shaped incoming and outgoing curves");check(projectFileToken(file)==hash,"curve edits crossfades clipboard split and save retain source audio bytes");dirty=false;perform(stop);
}
void Studio::runAudioFadeCurveTransportTick(){
    auto put=[&](const char* name,bool value){transportResults.getDynamicObject()->setProperty(name,value);};auto capture=[&](AlertWindow* dialog,const String& name){PNGImageFormat png;FileOutputStream stream(transportReport.getSiblingFile(name));return stream.openedOk()&&png.writeImageToStream(dialog->createComponentSnapshot(dialog->getLocalBounds()),stream);};
    if(transportTicks==3500){perform(stop);cancelNoteTool(false);PopupMenu::dismissAllActiveMenus();auto file=transportReport.getSiblingFile("native-curve-source.wav");put("nativeCurveFixture",makeCurveFixture(file));project=curveSong(file);currentFile={};selectedClip=-1;selectedTrack=0;undoStack.clear();redoStack.clear();publish();setPlaylistSelection({0,1},1);showPane(playlistPane);perform(audioCrossfadeOpen);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeCurveCrossfadeDialog",dialog&&dialog->getComboBoxComponent("curve")&&dialog->getWidth()<=650&&dialog->getHeight()<=400);if(dialog){dialog->getComboBoxComponent("curve")->setSelectedItemIndex(1,dontSendNotification);capture(dialog,"curve-crossfade-dialog.png");dialog->exitModalState(1);}}
    if(transportTicks==3505){put("nativeCurveCrossfadeApply",project.clips[0].fadeOutCurve==FadeCurve::equalPower&&project.clips[1].fadeInCurve==FadeCurve::equalPower&&undoStack.size()==1);perform(undoAction);bool restored=project.clips[0].fadeOutCurve==FadeCurve::linear;perform(redoAction);put("nativeCurveHistory",restored&&project.clips[0].fadeOutCurve==FadeCurve::equalPower);setPlaylistSelection({0,1},1);engine->observedPeak.store(0);engine->start();engine->seekRequested.store(3.5);transportFrames=engine->processedFrames.load();}
    if(transportTicks==3515){put("nativeCurveAudio",engine->playing.load()&&engine->processedFrames.load()>transportFrames&&engine->observedPeak.load()>.001f);perform(stop);perform(audioCrossfadeOpen);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeCurveReopen",dialog&&dialog->getComboBoxComponent("curve")&&dialog->getComboBoxComponent("curve")->getSelectedItemIndex()==1);if(dialog){dialog->getComboBoxComponent("curve")->setSelectedItemIndex(2,dontSendNotification);dialog->exitModalState(1);}}
    if(transportTicks==3520){put("nativeCurveSmooth",project.clips[0].fadeOutCurve==FadeCurve::sCurve&&project.clips[1].fadeInCurve==FadeCurve::sCurve&&undoStack.size()==2);setPlaylistSelection({0},0);perform(audioFadeCurvesOpen);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeCurveClipDialog",dialog&&dialog->getComboBoxComponent("inCurve")&&dialog->getComboBoxComponent("outCurve")&&dialog->getHeight()<=350);if(dialog){dialog->getComboBoxComponent("inCurve")->setSelectedItemIndex(1,dontSendNotification);dialog->getComboBoxComponent("outCurve")->setSelectedItemIndex(0,dontSendNotification);capture(dialog,"curve-clip-dialog.png");dialog->exitModalState(1);}}
    if(transportTicks==3525){put("nativeCurveIndependent",project.clips[0].fadeInCurve==FadeCurve::equalPower&&project.clips[0].fadeOutCurve==FadeCurve::linear&&undoStack.size()==3);perform(audioClipSettings);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeCurveSettingsButton",dialog&&dialog->getButton("Fade curves...")!=nullptr);if(dialog)dialog->exitModalState(3);}
    if(transportTicks==3530){auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeCurveSettingsOpen",dialog&&dialog->getName()=="Audio fade curves");if(dialog)dialog->exitModalState(0);}
    if(transportTicks==3535){put("nativeCurveCancel",!Component::getCurrentlyModalComponent()&&project.clips[0].fadeInCurve==FadeCurve::equalPower&&undoStack.size()==3);auto file=transportReport.getSiblingFile("native-fade-curves.pulse");Project read;put("nativeCurveSave",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.clips[0].fadeInCurve==FadeCurve::equalPower&&read.clips[1].fadeInCurve==FadeCurve::sCurve);snapshot(transportReport.getSiblingFile("native-curve-playlist.png"));perform(audioFadeCurvesOpen);if(auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent())){project.title="Newer curve edit";changed(false);dialog->getComboBoxComponent("inCurve")->setSelectedItemIndex(2,dontSendNotification);dialog->exitModalState(1);}}
    if(transportTicks==3540){put("nativeCurveStale",project.title=="Newer curve edit"&&project.clips[0].fadeInCurve==FadeCurve::equalPower&&undoStack.size()==3);perform(audioFadesClear);put("nativeCurveClear",project.clips[0].fadeIn==0&&project.clips[0].fadeInCurve==FadeCurve::linear);perform(undoAction);put("nativeCurveClearUndo",project.clips[0].fadeInCurve==FadeCurve::equalPower);}
}
